import{_ as a,o as r,c as t,am as n}from"./chunks/framework.BCmjHDVz.js";const h=JSON.parse('{"title":"Performance benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"manual/benchmarks.md","filePath":"manual/benchmarks.md","lastUpdated":null}'),s={name:"manual/benchmarks.md"};function o(i,e,l,c,m,d){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="Performance-benchmarks" tabindex="-1">Performance benchmarks <a class="header-anchor" href="#Performance-benchmarks" aria-label="Permalink to &quot;Performance benchmarks {#Performance-benchmarks}&quot;">​</a></h1><p>Copulas.jl uses two complementary benchmark systems.</p><h2 id="Performance-over-time" tabindex="-1">Performance over time <a class="header-anchor" href="#Performance-over-time" aria-label="Permalink to &quot;Performance over time {#Performance-over-time}&quot;">​</a></h2><p><a href="https://github.com/KristofferC/Tachometer.jl" target="_blank" rel="noreferrer">Tachometer</a> runs the native Julia suite on pull requests, compares changes with their merge base, and records default-branch results. Its dashboard is published alongside this documentation at <a href="https://lrnv.github.io/Copulas.jl/benchmarks/" target="_blank" rel="noreferrer">the Copulas.jl benchmark dashboard</a>.</p><h2 id="Comparison-with-R" tabindex="-1">Comparison with R <a class="header-anchor" href="#Comparison-with-R" aria-label="Permalink to &quot;Comparison with R {#Comparison-with-R}&quot;">​</a></h2><p>The cross-language suite compares Copulas.jl with R&#39;s <a href="https://cran.r-project.org/package=copula" target="_blank" rel="noreferrer"><code>copula</code></a> package. The initial set covers representative common operations rather than every family and dimension:</p><ul><li><p>Clayton, Gumbel, and Gaussian sampling;</p></li><li><p>Gumbel and Gaussian log-density evaluation;</p></li><li><p>pseudo-observations;</p></li><li><p>Gumbel inverse-Kendall fitting;</p></li><li><p>Gaussian maximum-likelihood fitting.</p></li></ul><p>Julia and R run as independent native processes on the same machine. The suite excludes process startup, package loading, fixture parsing, model construction, and Julia compilation. Full runs alternate three Julia and R process rounds and report the median steady-state time for each language.</p><p>Before reporting timings, deterministic outputs are compared numerically on shared committed fixtures. Sampling uses independent seeded streams and receives local range and finiteness checks. A failed correctness check invalidates the entire timing report.</p><p>The complete specification, locked environments, raw-result schema, and local reproduction instructions live in <a href="https://github.com/lrnv/Copulas.jl/tree/main/benchmark/cross_language" target="_blank" rel="noreferrer"><code>benchmark/cross_language</code></a>. Full reports are produced on releases and through the manually dispatched <strong>Julia vs R benchmarks</strong> workflow. The workflow attaches the raw JSON and rendered table as artifacts and includes the table in its job summary.</p><div class="tip custom-block"><div class="custom-block-title">Tip: Interpreting results</div><div class="custom-block-content"><p>GitHub-hosted runners are useful for reproducibility but are shared infrastructure. Their ratios are indicative, not universal claims about all hardware. Allocation figures are retained separately but are not compared because Julia and R memory instrumentation measures different things.</p></div></div><p>No full reference snapshot has been published yet. A snapshot should be added to <code>benchmark/cross_language/results/</code> only after its correctness report and runner metadata have been reviewed.</p>',12)])])}const p=a(s,[["render",o]]);export{h as __pageData,p as default};
